define([], function () {

    const CaseInfo = {
        contentCard: function (data, type, idx, active = false, otherAttributes = false) {
            const otherAttributesHtml = `
                                        <div class="otherAttributtesCtnClsCm">
                                            <div class="attributteCtnClsCm">
                                                <label for="resolutionTypeName">Tipo Doc. Sustento:</label>
                                                <input type="text" id="resolutionTypeName" name="resolutionTypeName" value="${data.resolutionTypeName || '---'}" readonly>
                                            </div>
                                            <div class="attributteCtnClsCm">
                                                <label for="resolutionDocument">Nro. Doc. Sustento:</label>
                                                <input type="text" id="resolutionDocument" name="resolutionDocument" value="${data.resolutionDocument || '---'}" readonly>
                                            </div>
                                        </div>
                                        <div class="otherAttributtesCtnClsCm">
                                            <div class="attributteCtnClsCm">
                                                <label for="floor">Tipo de Edificación:</label>
                                                <input type="text" id="floor" name="floor" value="${data.edificationTypeName || '---'}" readonly>
                                            </div>
                                            <div class="attributteCtnClsCm">
                                                <label for="municipalNumber">Número de edificación:</label>
                                                <input type="text" id="municipalNumber" name="municipalNumber" value="${data.edificationNumber || '---'}" readonly>
                                            </div>
                                        </div>
                                        <div class="otherAttributtesCtnClsCm">
                                            <div class="attributteCtnClsCm">
                                                <label for="floor">Tipo de interior:</label>
                                                <input type="text" id="floor" name="floor" value="${data.indoorTypeName || '---'}" readonly>
                                            </div>
                                            <div class="attributteCtnClsCm">
                                                <label for="municipalNumber">Número de interior:</label>
                                                <input type="text" id="municipalNumber" name="municipalNumber" value="${data.indoorNumber || '---'}" readonly>
                                            </div>
                                        </div> 
                                        <div class="otherAttributtesCtnClsCm">
                                            <div class="attributteCtnClsCm">
                                                <label for="floor">Piso:</label>
                                                <input type="text" id="floor" name="floor" value="${data.floor || '---'}" readonly>
                                            </div>
                                            <div class="attributteCtnClsCm">
                                                <label for="municipalNumber">Número municipal:</label>
                                                <input type="text" id="municipalNumber" name="municipalNumber" value="${data.municipalNumber || '---'}" readonly>
                                            </div>
                                        </div>                                  
                                        `;
            let addressValue;
            if (type === 'original') {
                addressValue = data.tipoDireccion === 1 ? data.urbanAddress : data.municipalAddress;
            } else {
                addressValue = data.address ? data.address.replace("None", '') : '';
            }
            // si data.address existe, reemplazar "None" por cadena vacía
            const cardHtml = `<div class="caseInfoClsCm">
                                <div class="headPredInfoClsCm ${type === 'original' ? 'headPredInfoOriginalClsCm' : 'headPredInfoResultClsCm'}">
                                    <span class="alignVCenter">Predio: ${data.cup || idx}</span>
                                    <button class="zoomPredInfoClsCm ${type === 'original' ? 'active' : null} toolsPredInfoClsCm" data-cup=${data.cup}>
                                        <i class="fa fa-search" style="width: 16px; height: 16px"></i>
                                    </button>
                                    <button class="colapsePredInfoClsCm toolsPredInfoClsCm">
                                        <i class='fas fa-angle-down' style="width: 16px; height: 16px"></i>
                                    </button>
                                </div>
                                <div class="bodyPredInfoClsCm ${active ? 'active' : null}">
                                    <label for="direccion">Dirección:</label>
                                    <textarea readonly class="auto-resize-textarea">${addressValue}</textarea>
                                    ${otherAttributes ? otherAttributesHtml : ''}
                                </div>
                            </div>`;
            return cardHtml;
        },
        // Otras funciones o propiedades
        buildLandAttributesContent: function (land, domains) {
            // console.log(domains);
            const tipUuItem = domains.uuType.find(item => item.id === land.uuType && item.estado === 1);
            const tipUuText = tipUuItem ? tipUuItem.name : land.uuType;
            // const tipViaItem = domains.codStreet.find(item => item.id === land.streetType && item.estado === 1);
            // const tipViaText = tipViaItem ? tipViaItem.name : land.streetType;
            const tipDocItem = domains.resolutionType.find(item => item.id === land.resolutionType && item.estado === 1);
            const tipDocText = tipDocItem ? tipDocItem.name : land.resolutionType;
            const tipEdificacionItem = domains.tipoEdificacion.find(item => item.id === land.edificationType && item.estado === 1);
            const tipEdificacionText = tipEdificacionItem ? tipEdificacionItem.name : land.edificationType;
            const tipInteriorItem = domains.tipoInterior.find(item => item.id === land.indoorType && item.estado === 1);
            const tipInteriorText = tipInteriorItem ? tipInteriorItem.name : land.indoorType;
            // construir tabla de atributos
            // let attributesHtml = `<tr><th colspan="2"><strong>Detalles del Predio</strong></th></tr>`;
            const htmlTbody = `
                <tbody>
                    <tr style="font-weight:bold; background:#f0f0f0;">
                        <th colspan="2" style="border-bottom: 1px solid #ccc;">CPU: ${land.cup}</th>
                    </tr>
                    <tr><td valign="top" colspan="2" style="border-bottom: 1px solid #ccc;"></strong></td></tr>
                    <tr><td valign="top"><strong>CPM</strong></td><td>: ${land.cpm || ''}</td></tr>
                    <tr><td valign="top"><strong>CUC</strong></td><td>: ${land.codCuc || ''}</td></tr>
                    <tr><td valign="top"><strong>Tipo unidad urb.</strong></td><td>: ${tipUuText || ''}</td></tr>
                    <tr><td valign="top"><strong>Unidad urb.</strong></td><td>: ${land.habilitacionName || ''}</td></tr>
                    <tr><td valign="top"><strong>Manzana urb.</strong></td><td>: ${land.urbanMza || ''}</td></tr>
                    <tr><td valign="top"><strong>Lote urb.</strong></td><td>: ${land.urbanLotNumber || ''}</td></tr>
                    <tr><td valign="top"><strong>Sublote</strong></td><td>: ${land.urbanSublotNumber || ''}</td></tr>
                    <tr><td valign="top"><strong>Tip. edificación</strong></td><td>: ${tipEdificacionText || ''}</td></tr>        
                    <tr><td valign="top"><strong>Num. edificación</strong></td><td>: ${land.edificationNumber || ''}</td></tr>
                    <tr><td valign="top"><strong>Tip. interior</strong></td><td>: ${tipInteriorText || ''}</td></tr>
                    <tr><td valign="top"><strong>Num. interior</strong></td><td>: ${land.indoorNumber || ''}</td></tr>
                    <tr><td valign="top"><strong>Tipo de vía</strong></td><td>: ${land.streetTypeName || ''}</td></tr>
                    <tr><td valign="top"><strong>Nombre de vía</strong></td><td>: ${land.streetName || ''}</td></tr>
                    <tr><td valign="top"><strong>Número domicilario</strong></td><td>: ${land.municipalNumber || ''}</td></tr>
                    <tr><td valign="top"><strong>Block</strong></td><td>: ${land.block || ''}</td></tr>
                    <tr><td valign="top"><strong>Piso</strong></td><td>:  ${land.floor || ''}</td></tr>
                    <tr><td valign="top"><strong>Kilometro</strong></td><td>:  ${land.km || ''}</td></tr>
                    <tr><td valign="top"><strong>Tipo documento</strong></td><td>: ${tipDocText || ''}</td></tr>
                    <tr><td valign="top"><strong>Documento</strong></td><td>: ${land.resolutionDocument || ''}</td></tr>
                    <tr><td valign="top"><strong>Origen de info.</strong></td><td>: ${land.sourceInformation || ''}</td></tr>
                    <tr><td valign="top"><strong>Arancel</strong></td><td>: ${land.valAct || ''} </td></tr>       
                </tbody>
            `;

            return htmlTbody;
        },
    };

    return CaseInfo;
});